class ProfileScreen extends ConsumerWidget { const ProfileScreen({super.key}); @override Widget build(BuildContext context, WidgetRef ref) { final strings = AppStrings(Localizations.localeOf(context)); final user = ref.watch(authProvider).value?.user; final settings = ref.watch(settingsProvider); if (user == null) return const SizedBox.shrink(); return ListView(padding: const EdgeInsets.fromLTRB(20, 24, 20, 34), children: [Center(child: CircleAvatar(radius: 43, backgroundColor: AppTheme.violet.withOpacity(.15), backgroundImage: user.avatarUrl == null ? null : NetworkImage(user.avatarUrl!), child: user.avatarUrl == null ? Text(_initial(user.displayName), style: const TextStyle(fontSize: 30, color: AppTheme.violet, fontWeight: FontWeight.w900)) : null)), const SizedBox(height: 13), Center(child: Text(user.displayName, style: Theme.of(context).textTheme.headlineSmall?.copyWith(fontWeight: FontWeight.w900))), Center(child: Text('@${user.username}  ·  Level ${user.level}', style: TextStyle(color: Theme.of(context).colorScheme.onSurfaceVariant))), const SizedBox(height: 24), Row(children: [_StatCard(label: strings.coins, value: '${user.coins}', icon: Icons.circle, color: AppTheme.gold), const SizedBox(width: 10), _StatCard(label: strings.pips, value: '${user.pips}', icon: Icons.brightness_1_rounded, color: AppTheme.violet), const SizedBox(width: 10), _StatCard(label: 'XP', value: '${user.experience}', icon: Icons.bolt_rounded, color: AppTheme.coral)]), const SizedBox(height: 26), Text(strings.settings, style: const TextStyle(fontSize: 18, fontWeight: FontWeight.w900)), const SizedBox(height: 10), Card(child: Column(children: [ListTile(leading: const Icon(Icons.brightness_6_outlined), title: Text(strings.isPersian ? 'پوسته' : 'Appearance'), trailing: DropdownButton<ThemeChoice>(value: settings.theme, underline: const SizedBox.shrink(), items: [DropdownMenuItem(value: ThemeChoice.system, child: Text('System')), DropdownMenuItem(value: ThemeChoice.light, child: Text(strings.light)), DropdownMenuItem(value: ThemeChoice.dark, child: Text(strings.dark))], onChanged: (value) { if (value != null) { ref.read(settingsProvider.notifier).setTheme(value); ref.read(authProvider.notifier).updatePreferences(theme: value).catchError((_) { if (context.mounted) ScaffoldMessenger.of(context).showSnackBar(const SnackBar(content: Text('Appearance saved on this device.'))); }); } })), const Divider(height: 1), ListTile(leading: const Icon(Icons.translate_rounded), title: Text(strings.language), trailing: SegmentedButton<AppLocale>(segments: const [ButtonSegment(value: AppLocale.en, label: Text('EN')), ButtonSegment(value: AppLocale.fa, label: Text('FA'))], selected: {settings.locale}, onSelectionChanged: (value) { final locale = value.first; ref.read(settingsProvider.notifier).setLocale(locale); ref.read(authProvider.notifier).updatePreferences(locale: locale).catchError((_) { if (context.mounted) ScaffoldMessenger.of(context).showSnackBar(const SnackBar(content: Text('Language saved on this device.'))); }); }))])), const SizedBox(height: 18), ListTile(tileColor: Theme.of(context).colorScheme.surface, shape: RoundedRectangleBorder(borderRadius: BorderRadius.circular(16)), leading: const Icon(Icons.emoji_events_rounded, color: AppTheme.gold), title: const Text('Season leaderboard', style: TextStyle(fontWeight: FontWeight.w800)), trailing: const Icon(Icons.chevron_right_rounded), onTap: () => Navigator.of(context).push(MaterialPageRoute(builder: (_) => const LeaderboardScreen()))), const SizedBox(height: 10), if (user.role == 'admin' || user.role == 'moderator') ListTile(tileColor: Theme.of(context).colorScheme.surface, shape: RoundedRectangleBorder(borderRadius: BorderRadius.circular(16)), leading: const Icon(Icons.admin_panel_settings_rounded, color: AppTheme.violet), title: const Text('Admin console', style: TextStyle(fontWeight: FontWeight.w800)), trailing: const Icon(Icons.chevron_right_rounded), onTap: () => Navigator.of(context).push(MaterialPageRoute(builder: (_) => const AdminScreen()))), const SizedBox(height: 10), OutlinedButton.icon(onPressed: () => _logout(context, ref), icon: const Icon(Icons.logout_rounded), label: Text(strings.signOut), style: OutlinedButton.styleFrom(foregroundColor: Theme.of(context).colorScheme.error))]); }
  String _initial(String value) {
    final trimmed = value.trim();
    return trimmed.isEmpty ? 'V' : trimmed.substring(0, 1).toUpperCase();
  }

  Future<void> _logout(BuildContext context, WidgetRef ref) async {
    final shouldLogout = await showDialog<bool>(context: context, builder: (dialogContext) => AlertDialog(title: const Text('Sign out?'), content: const Text('You can sign back in whenever you are ready.'), actions: [TextButton(onPressed: () => Navigator.of(dialogContext).pop(false), child: const Text('Cancel')), FilledButton(onPressed: () => Navigator.of(dialogContext).pop(true), child: const Text('Sign out'))]));
    if (shouldLogout == true) await ref.read(authProvider.notifier).logout();
  }
}

class _StatCard extends StatelessWidget { const _StatCard({required this.label, required this.value, required this.icon, required this.color}); final String label; final String value; final IconData icon; final Color color; @override Widget build(BuildContext context) => Expanded(child: Card(child: Padding(padding: const EdgeInsets.symmetric(vertical: 15), child: Column(children: [Icon(icon, color: color, size: 19), const SizedBox(height: 6), Text(value, style: const TextStyle(fontWeight: FontWeight.w900, fontSize: 17)), Text(label, style: TextStyle(fontSize: 11, color: Theme.of(context).colorScheme.onSurfaceVariant))])))); }
